function countTilings(n: number): number {
  const MOD = 1_000_000_007;
  const full = new Array(n + 1).fill(0), part = new Array(n + 1).fill(0);
  full[0] = 1;
  full[1] = 1;
  for (let i = 2; i <= n; i++) {
    full[i] = (full[i - 1] + full[i - 2] + 2 * part[i - 1]) % MOD;
    part[i] = (full[i - 2] + part[i - 1]) % MOD;
  }
  return full[n];
}

