function countTilings(n: number): number {
  const MOD = 1_000_000_007;
  let a = 1, b = 1, c = 2; // f(0), f(1), f(2)
  if (n === 1) return 1;
  for (let i = 3; i <= n; i++) [a, b, c] = [b, c, (2 * c + a) % MOD];
  return c;
}

